exercise.solution:
data class Build(val id: Int, val branch: String, val durationSec: Int, val status: String)

val builds = listOf(
    Build(1, "main", 180, "SUCCESS"),
    Build(2, "feature/login", 240, "FAILED"),
    Build(3, "main", 120, "SUCCESS"),
    Build(4, "feature/login", 300, "FAILED"),
    Build(5, "hotfix", 60, "SUCCESS"),
    Build(6, "main", 200, "CANCELED"),
)

fun main() {
    // 1. partition 은 한 번 순회로 두 갈래를 만든다 — filter + filterNot 두 번 도는 것보다 낫다.
    val (ok, rest) = builds.partition { it.status == "SUCCESS" }
    println("성공 ${ok.size}건 / 그 외 ${rest.size}건")

    // 2. filter { }.size 는 리스트를 하나 더 만든다. 개수만 필요하면 count.
    println(builds.count { it.status == "FAILED" })

    // 3.
    println(builds.filter { it.status == "SUCCESS" }.map { it.durationSec }.average())

    // 4. 빈 컬렉션이면 null 이 나오는 ...OrNull 을 쓰고 ?: 로 받는다. maxBy { }!! 는 최악.
    println(builds.maxByOrNull { it.durationSec }?.id ?: -1)

    // 5. groupBy + mapValues 와 달리 그룹마다 중간 List 를 만들지 않는다.
    println(builds.groupingBy { it.branch }.fold(0) { acc, b -> acc + b.durationSec }.toSortedMap())

    // 6. runningFold 는 초기값까지 포함해 누적 과정을 전부 남긴다 (원소 6개 → 결과 7개).
    println(builds.runningFold(0) { acc, b -> acc + b.durationSec })
}
